-- Retire shared QR routing while preserving every existing table UUID and history.
ALTER TABLE "cafe_tables" ADD COLUMN "customerQrEnabled" BOOLEAN NOT NULL DEFAULT false;

UPDATE "cafe_tables"
SET
  "name" = CASE "id"
    WHEN '40000000-0000-4000-8000-000000000005' THEN '5'
    WHEN '40000000-0000-4000-8000-000000000006' THEN '6'
    WHEN '40000000-0000-4000-8000-000000000007' THEN '7'
    WHEN '40000000-0000-4000-8000-000000000008' THEN '8'
    WHEN '40000000-0000-4000-8000-000000000009' THEN '9'
    WHEN '40000000-0000-4000-8000-000000000010' THEN '10'
    WHEN '40000000-0000-4000-8000-000000000011' THEN '11'
    WHEN '40000000-0000-4000-8000-000000000013' THEN '12'
    WHEN '40000000-0000-4000-8000-000000000014' THEN '13'
    WHEN '40000000-0000-4000-8000-000000000015' THEN '14'
    WHEN '40000000-0000-4000-8000-000000000016' THEN '15'
    ELSE "name"
  END,
  "displayOrder" = CASE "id"
    WHEN '40000000-0000-4000-8000-000000000001' THEN 1
    WHEN '40000000-0000-4000-8000-000000000002' THEN 2
    WHEN '40000000-0000-4000-8000-000000000003' THEN 3
    WHEN '40000000-0000-4000-8000-000000000004' THEN 4
    WHEN '40000000-0000-4000-8000-000000000005' THEN 5
    WHEN '40000000-0000-4000-8000-000000000006' THEN 6
    WHEN '40000000-0000-4000-8000-000000000007' THEN 7
    WHEN '40000000-0000-4000-8000-000000000008' THEN 8
    WHEN '40000000-0000-4000-8000-000000000009' THEN 9
    WHEN '40000000-0000-4000-8000-000000000010' THEN 10
    WHEN '40000000-0000-4000-8000-000000000011' THEN 11
    WHEN '40000000-0000-4000-8000-000000000013' THEN 12
    WHEN '40000000-0000-4000-8000-000000000014' THEN 13
    WHEN '40000000-0000-4000-8000-000000000015' THEN 14
    WHEN '40000000-0000-4000-8000-000000000016' THEN 15
    ELSE "displayOrder"
  END,
  "customerQrEnabled" = CASE
    WHEN "id" IN (
      '40000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000002',
      '40000000-0000-4000-8000-000000000003', '40000000-0000-4000-8000-000000000004',
      '40000000-0000-4000-8000-000000000005', '40000000-0000-4000-8000-000000000006',
      '40000000-0000-4000-8000-000000000007', '40000000-0000-4000-8000-000000000008',
      '40000000-0000-4000-8000-000000000009', '40000000-0000-4000-8000-000000000010',
      '40000000-0000-4000-8000-000000000011', '40000000-0000-4000-8000-000000000013',
      '40000000-0000-4000-8000-000000000014'
    ) THEN true
    ELSE false
  END
WHERE "id" IN (
  '40000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000002',
  '40000000-0000-4000-8000-000000000003', '40000000-0000-4000-8000-000000000004',
  '40000000-0000-4000-8000-000000000005', '40000000-0000-4000-8000-000000000006',
  '40000000-0000-4000-8000-000000000007', '40000000-0000-4000-8000-000000000008',
  '40000000-0000-4000-8000-000000000009', '40000000-0000-4000-8000-000000000010',
  '40000000-0000-4000-8000-000000000011', '40000000-0000-4000-8000-000000000013',
  '40000000-0000-4000-8000-000000000014', '40000000-0000-4000-8000-000000000015',
  '40000000-0000-4000-8000-000000000016'
);

UPDATE "cafe_tables"
SET "isActive" = false, "archivedAt" = CURRENT_TIMESTAMP, "customerQrEnabled" = false
WHERE "id" = '40000000-0000-4000-8000-000000000012';

UPDATE "table_qr_credentials"
SET "isActive" = false, "rotatedAt" = CURRENT_TIMESTAMP;

ALTER TABLE "cafe_tables" DROP CONSTRAINT "cafe_tables_qrFamilyId_fkey";
ALTER TABLE "table_qr_credentials" DROP CONSTRAINT "table_qr_credentials_qrFamilyId_fkey";
DROP INDEX "cafe_tables_qrFamilyId_idx";
DROP INDEX "table_qr_credentials_qrFamilyId_idx";
ALTER TABLE "cafe_tables" DROP COLUMN "qrFamilyId";
ALTER TABLE "table_qr_credentials" DROP COLUMN "qrFamilyId";
DROP TABLE "table_qr_families";

CREATE INDEX "cafe_tables_customerQrEnabled_idx" ON "cafe_tables"("customerQrEnabled");
